import pandas as pd
import ast

tasks = pd.read_csv('/app/dataset/tasks.csv')
timesheet = pd.read_csv('/app/dataset/timesheet.csv')

task_pays = tasks.set_index('task_id')['pay_per_completion'].to_dict()

def parse_tasks(t_str):
    t_str = t_str.strip()
    if not t_str.startswith('['):
        t_str = '[' + t_str
    if not t_str.endswith(']'):
        t_str = t_str + ']'
    try:
        return ast.literal_eval(t_str)
    except Exception:
        import re
        nums = re.findall(r'\d+', t_str)
        return [int(n) for n in nums]

timesheet['parsed_tasks'] = timesheet['performed_tasks'].apply(parse_tasks)

mismatches = []
for idx, r in timesheet.iterrows():
    pts = r['parsed_tasks']
    # only consider rows where all tasks are valid
    if all(t in task_pays for t in pts):
        computed_bonus = sum(task_pays[t] for t in pts)
        given_bonus = r['bonus']
        if abs(computed_bonus - given_bonus) > 1e-5:
            mismatches.append((idx, r['id'], pts, given_bonus, computed_bonus))

print('Number of rows with only valid tasks but mismatching bonus column:', len(mismatches))
for item in mismatches[:10]:
    print(item)
