tasks = pd.read_csv('/app/dataset/tasks.csv')
timesheet = pd.read_csv('/app/dataset/timesheet.csv')

mapping = {
    62020111425: 65020111422,
    84731091580: 87031491580,
    68011910138: 68011810139,
    16102016795: 96102016751,
    15720759071: 75020759171
}
timesheet['employee_id'] = timesheet['employee_id'].replace(mapping)

def parse_tasks(t_str):
    t_str = t_str.strip()
    if not t_str.startswith('['):
        t_str = '[' + t_str
    if not t_str.endswith(']'):
        t_str = t_str + ']'
    try:
        return ast.literal_eval(t_str)
    except Exception:
        import re
        nums = re.findall(r'\d+', t_str)
        return [int(n) for n in nums]

timesheet['parsed_tasks'] = timesheet['performed_tasks'].apply(parse_tasks)

def parse_date(d_str):
    try:
        parts = d_str.split('-')
        return datetime.date(int(parts[0]), int(parts[1]), int(parts[2]))
    except Exception:
        return None

timesheet['parsed_date'] = timesheet['date'].apply(parse_date)

valid_tasks = set(tasks['task_id'])
task_pays = tasks.set_index('task_id')['pay_per_completion'].to_dict()
emp_rates = employees.set_index('PESEL')['hourly_rate'].to_dict()

def get_billing_month(dt):
    if dt is None:
        return None
    if datetime.date(2025, 3, 4) <= dt <= datetime.date(2025, 3, 31):
        return '2025-03'
    elif datetime.date(2025, 4, 1) <= dt <= datetime.date(2025, 5, 5):
        return '2025-04'
    elif datetime.date(2025, 5, 6) <= dt <= datetime.date(2025, 6, 2):
        return '2025-05'
    elif datetime.date(2025, 6, 3) <= dt <= datetime.date(2025, 6, 30):
        return '2025-06'
    return None

timesheet['billing_month'] = timesheet['parsed_date'].apply(get_billing_month)

def compute_salaries(exclude_row_on_invalid_task=False):
    salaries = {}
    for pesel in employees['PESEL']:
        salaries[str(pesel)] = {
            '2025-03': {'hours': 0, 'bonus': 0},
            '2025-04': {'hours': 0, 'bonus': 0},
            '2025-05': {'hours': 0, 'bonus': 0},
            '2025-06': {'hours': 0, 'bonus': 0}
        }

    for idx, r in timesheet.iterrows():
        try:
            emp_id = r['employee_id']
            b_month = r['billing_month']

            if b_month is None:
                continue

            if r['hours_worked'] <= 0:
                continue

            pts = r['parsed_tasks']
            has_invalid_task = any(t not in valid_tasks for t in pts)

            if has_invalid_task and exclude_row_on_invalid_task:
                continue

            emp_str = str(emp_id)
            if emp_str in salaries:
                salaries[emp_str][b_month]['hours'] += r['hours_worked']
                row_bonus = sum(task_pays[t] for t in pts if t in valid_tasks)
                salaries[emp_str][b_month]['bonus'] += row_bonus
        except Exception as e:
            print('Error in loop at index:', idx)
            traceback.print_exc()
            raise e

    final_salaries = {}
    for emp_str, months_data in salaries.items():
        try:
            rate = emp_rates[int(emp_str)]
            emp_salaries = []
            for m in sorted(months_data.keys()):
                hours = months_data[m]['hours']
                bonus = months_data[m]['bonus']
                total = hours * rate + bonus
                emp_salaries.append(round(total))
            final_salaries[emp_str] = emp_salaries
        except Exception as e:
            print('Error in final aggregation for:', emp_str)
            traceback.print_exc()
            raise e

    return final_salaries

s_A = compute_salaries(exclude_row_on_invalid_task=False)
